﻿:root {
  color-scheme: dark;
  --ink: #090b0a;
  --panel: #0d100e;
  --panel-raised: #111512;
  --line: #2b322d;
  --muted: #858c85;
  --paper: #e9eee8;
  --green: #20ef4f;
  --green-dim: #087d2a;
