.folder-panel { position: relative; display: flex; flex-direction: column; min-height: 270px; overflow: hidden; transform: scaleY(var(--crt-s)); border: 1px solid var(--line); border-radius: 4px; background: #080d09; box-shadow: inset 0 0 28px color-mix(in srgb, var(--green) 9%, transparent); }
