        event.preventDefault();
        if (Model.state.screen === "experience" && Model.state.activeFolder === folderRoute.dataset.routeFolder) {
          window.location.reload();
        } else {
          View.renderExperienceFolder(folderRoute.dataset.routeFolder);
          history.pushState({ screen: "experience", folder: folderRoute.dataset.routeFolder }, "", folderRoute.href);
        }
        return;
      }

      const sectionRoute = event.target.closest("[data-route-section]");
      if (sectionRoute) {
        event.preventDefault();
        const screenId = sectionRoute.dataset.routeSection;
        if (screenId === Model.state.screen) {
          if (screenId === "experience" && Model.state.activeFolder) {
            View.collapseExperienceFolder();
            history.pushState({ screen: screenId }, "", sectionRoute.href);
          } else {
            window.location.reload();
          }
        } else {
          this.goTo(screenId);
        }
        return;
      }

