.theme-orb::before { position: absolute; inset: -7px; border: 1px solid var(--green); border-radius: 50%; content: ""; }
.theme-picker:hover .theme-orb { transform: scale(1.06); box-shadow: 0 0 18px 4px var(--orb-glow), inset 0 0 12px var(--orb-glow); }
