.theme-picker[data-selected-theme="cyberpunk"] .theme-orb-next { --orb-core: #010602; --orb-glow: #20ef4f; --orb-accent: #20ef4f; background: radial-gradient(circle, #010602 0 39%, color-mix(in srgb, #20ef4f 75%, #010602) 74%, #20ef4f 100%); box-shadow: 0 0 13px 3px #20ef4f, inset 0 0 12px #20ef4f; }
