*** Begin Patch
*** Update File: styles.css
@@
 .route-bar { gap: 4px; }
 .page-controls { justify-content: space-between; }
 .keyboard-hint { margin-left: 0; }
+.control-pickers { display: flex; align-items: center; gap: 8px; }
 .theme-picker { position: relative; z-index: 8; isolation: isolate; flex: 0 0 56px; width: 56px; height: 56px; margin-left: 0; transition: flex-basis .25s ease, width .25s ease; }
@@
 .theme-choice[data-theme-choice="hacker"] .theme-orb { --orb-core: #010602; --orb-glow: #20ef4f; --orb-accent: #20ef4f; }
 .theme-choice[data-theme-choice="cyberpunk"] .theme-orb { --orb-core: #080406; --orb-glow: #ed1b2e; --orb-accent: #ed1b2e; }
 .theme-choice[data-theme-choice="claude"] .theme-orb { --orb-core: #fff4df; --orb-glow: #d35445; --orb-accent: #d35445; }
+.language-picker { position: relative; z-index: 8; isolation: isolate; flex: 0 0 56px; width: 56px; height: 56px; transition: flex-basis .25s ease, width .25s ease; }
+.language-picker:hover, .language-picker:focus-within { flex-basis: 112px; width: 112px; }
+.language-picker.is-collapsed, .language-picker.is-collapsed:hover, .language-picker.is-collapsed:focus-within { flex-basis: 56px; width: 56px; }
+.language-picker::before { position: absolute; z-index: 0; inset: 2px; border: 1px solid var(--green); border-radius: 999px; background: var(--ink); content: ""; opacity: 0; pointer-events: none; transition: opacity .2s ease; }
+.language-picker:hover::before, .language-picker:focus-within::before { opacity: 1; }
+.language-picker.is-collapsed::before, .language-picker.is-collapsed:hover::before, .language-picker.is-collapsed:focus-within::before { opacity: 0; }
+.language-current, .language-choice { position: absolute; z-index: 1; top: 0; width: 56px; height: 56px; display: grid; place-items: center; }
+.language-current { left: 0; }
+.language-choice { left: 56px; padding: 0; border: 0; background: transparent; cursor: pointer; opacity: 0; pointer-events: none; transition: opacity .2s ease; }
+.language-picker:hover .language-choice, .language-picker:focus-within .language-choice { opacity: 1; pointer-events: auto; }
+.language-picker.is-collapsed .language-choice, .language-picker.is-collapsed:hover .language-choice, .language-picker.is-collapsed:focus-within .language-choice { opacity: 0; pointer-events: none; }
+.language-orb { --language-accent: #ed1b2e; position: relative; width: 30px; height: 30px; overflow: hidden; border: 1px solid color-mix(in srgb, var(--language-accent) 70%, var(--paper)); border-radius: 50%; box-shadow: 0 0 13px 3px color-mix(in srgb, var(--language-accent) 55%, transparent); }
+.language-picker[data-selected-language="es"] .language-current .language-orb,
+.language-choice[data-language-choice="es"] .language-orb { --language-accent: #c82d34; background: radial-gradient(circle at 35% 28%, rgba(255, 255, 255, .45), transparent 42%), linear-gradient(to bottom, #c82d34 0 27%, #f6c445 27% 73%, #c82d34 73%); }
+.language-picker[data-selected-language="en"] .language-current .language-orb,
+.language-choice[data-language-choice="en"] .language-orb { --language-accent: #234078; background: radial-gradient(circle at 35% 28%, rgba(255, 255, 255, .45), transparent 42%), linear-gradient(32deg, transparent 43%, #fff 43% 49%, #c83245 49% 55%, #fff 55% 61%, transparent 61%), linear-gradient(-32deg, transparent 43%, #fff 43% 49%, #c83245 49% 55%, #fff 55% 61%, transparent 61%), linear-gradient(90deg, transparent 40%, #fff 40% 60%, transparent 60%), linear-gradient(0deg, transparent 38%, #fff 38% 62%, transparent 62%), #234078; }
+.language-choice:hover .language-orb, .language-choice:focus-visible .language-orb { box-shadow: 0 0 18px 6px color-mix(in srgb, var(--language-accent) 70%, transparent); }
 .experience-explorer { position: relative; display: grid; grid-template-columns: minmax(185px, .7fr) minmax(0, 1.3fr); gap: 20px; align-items: stretch; }
*** End Patch

