      skills: this.dir(skills),
      experience: this.dir(experience),
      contact: this.dir(contact),
    });
  },

  walk(root, parts) {
    let node = root;
    for (const part of parts) {
      if (node.type !== "dir" || !Object.hasOwn(node.children, part)) return null;
      node = node.children[part];
    }
    return node;
