          ["Role", T.t("infoRole")],
          ["Focus", T.t("infoFocus")],
          ["Location", T.t("infoLocation")],
          ["Theme", Model.state.theme],
          ["Language", Model.locale],
          ["Shell", "vsh"],
          ["Uptime", T.t("infoUptime", { minutes: Math.max(1, Math.round(performance.now() / 60000)) })],
        ];
