const errs=[]; page.on('pageerror',e=>errs.push(e.message));
const run = (c)=>page.evaluate((c)=>{const i=document.querySelector('.terminal-input');i.value=c;i.closest('form').requestSubmit();}, c);
await page.evaluate(()=>document.querySelector('.terminal-toggle').click());
await run('help'); const helpHidden = await page.evaluate(()=>/matrix|ping|rm /.test(document.querySelector('.terminal-log').innerText));
await run('rm foo'); await run('rm -rf /');
await page.waitForTimeout(3500);
const mid = await page.evaluate(()=>({busy:TerminalApp.busy, wiping:document.querySelector('#stage').classList.contains('is-wiping')}));
await page.keyboard.press('Control+c');
const after = await page.evaluate(()=>({busy:TerminalApp.busy, wiping:document.querySelector('#stage').classList.contains('is-wiping')}));
await run('ping'); await page.waitForTimeout(4800);
await run('matrix'); await page.waitForTimeout(600);
const canvas = await page.evaluate(()=>!!document.querySelector('.terminal-matrix'));
