ping: {
  hidden: true,
  usage: "ping [host]",
  run(ctx) {
    const T = TerminalCommands;
    const host = ctx.args[0] || "victor";
    const ip = "127.0.0.1";
    const steps = [{ text: T.t("pingStart", { host, ip }), wait: 600 }];
    for (let seq = 0; seq < 4; seq += 1) {
      const time = (0.4 + Math.random() * 1.2).toFixed(2);
      steps.push({ text: T.t("pingReply", { ip, seq, time }), wait: 700 });
    }
    steps.push(
      { text: "" },
      { text: T.t("pingStats", { host }), wait: 120 },
      { text: T.t("pingSummary"), wait: 120 },
      { text: T.t("pingStatus"), kind: "accent", wait: 0 },
    );
    ctx.play(steps);
  },
},

