  },

  // Resolves an argument to an existing node, printing the proper error when it cannot.
  lookup(ctx, input) {
    const parts = ctx.resolve(input);
    const node = parts && ctx.node(parts);
    if (!node) {
      ctx.print(this.t("noSuchFile", { name: input }), "err");
      return null;
    }
    return { parts, node };
