  this.bindKonami();
},

bindKonami() {
  const code = ["ArrowUp", "ArrowUp", "ArrowDown", "ArrowDown", "ArrowLeft", "ArrowRight", "ArrowLeft", "ArrowRight", "b", "a"];
  let progress = 0;
  document.addEventListener("keydown", (event) => {
    const field = event.target.closest?.("input, textarea");
    if (field && field !== this.els.input) return;
    if (event.repeat || ["Shift", "Control", "Alt", "Meta", "CapsLock"].includes(event.key)) return;
    const key = event.code === "KeyB" ? "b" : event.code === "KeyA" ? "a" : event.key;
    if (key !== code[progress]) {
      progress = key === code[0] ? 1 : 0;
      return;
    }
    progress += 1;
    if (progress < code.length) return;
    progress = 0;
    event.preventDefault();
    this.unlockKonami();
  });
},

unlockKonami() {
  if (this.busy) return;
  if (!this.isOpen) this.setOpen(true);
  const T = TerminalCommands;
  this.print("↑ ↑ ↓ ↓ ← → ← → B A", "accent");
  this.print(T.t("konami"), "accent");
  this.print(T.t("konamiHint"), "dim");
  this.els.input.value = "";
  this.matrix(5000);
},

