return await page.evaluate(async()=>{
const btn=document.querySelector('[data-folder="projects"]'), st=document.querySelector('#stage').getBoundingClientRect();
const bb=btn.getBoundingClientRect();
const ev=(t,x,y)=>new PointerEvent(t,{pointerId:1,isPrimary:true,button:0,bubbles:true,clientX:x,clientY:y});
btn.setPointerCapture=()=>{};
btn.dispatchEvent(ev('pointerdown',bb.x+10,bb.y+10));
btn.dispatchEvent(ev('pointermove',bb.x+60,bb.y+60));
const dragging=btn.classList.contains('is-dragging');
btn.dispatchEvent(ev('pointerup',st.x+st.width/2,st.y+st.height/2));
await new Promise(r=>setTimeout(r,600));
return {dragging,active:Model.state.activeFolder,hash:location.hash,returning:btn.classList.contains('is-returning')};
})

