// navegación
r.nav=[];
for(const s of ['about','skills','experience','contact','home']){
  await ev(s=>document.querySelector(`[data-route="${s}"]`).click(),s); await page.waitForTimeout(150);
  r.nav.push(await ev(()=>[Model.state.screen,document.querySelector('.screen.is-active')?.dataset.screen,location.hash].join('|')));
}
// skills renderizadas
await ev(()=>document.querySelector('[data-route="skills"]').click());
