const snap = () => page.evaluate(() => { const o=[]; document.querySelectorAll('body, body *').forEach((e,i)=>{const c=getComputedStyle(e); o.push(i+e.tagName+'.'+e.className+'|'+c.cssText.length+'|'+['color','backgroundColor','display','width','height','padding','margin','border','fontSize','opacity','transform','gridTemplateColumns','position','boxShadow','backgroundImage'].map(k=>c[k]).join(';'));}); return o;});
const res={};
for (const [w,h] of [[1280,800],[700,600],[400,700]]) {
  await page.setViewportSize({width:w,height:h});
  for (const th of ['hacker','cyberpunk','claude']) {
    await page.evaluate(t=>document.body.dataset.theme=t, th);
    await page.waitForTimeout(150);
    res[w+th+'new']=await snap();
  }
}
await page.evaluate(()=>{document.querySelectorAll('link[rel=stylesheet]').forEach(l=>{const h=l.getAttribute('href'); if(/functions\/(orbs|virtualFolders|experience|contactForm)/.test(h)) l.remove(); else if(h.includes('CSS/styles.css')) l.href='assets/CSS/_old.css';});});
await page.waitForTimeout(800);
let diffs=[];
for (const [w,h] of [[1280,800],[700,600],[400,700]]) {
  await page.setViewportSize({width:w,height:h});
  for (const th of ['hacker','cyberpunk','claude']) {
    await page.evaluate(t=>document.body.dataset.theme=t, th);
    await page.waitForTimeout(150);
    const old=await snap(); const nw=res[w+th+'new'];
    old.forEach((x,i)=>{ if(x!==nw[i]) diffs.push(w+th+' '+x+' => '+nw[i]);});
  }
}
return {n:diffs.length, sample:diffs.slice(0,8)};

