// Dino game adapted from https://github.com/emilioaor/juego-dinosaurio-sin-internet
(() => {
  const canvas = document.getElementById("dino-canvas");
  if (!canvas) return;
  const ctx = canvas.getContext("2d");
  const sprite = (name) => {
    const img = new Image();
    img.src = `assets/dinoGame/sprites/${name}.png`;
    return img;
  };
  const clouds = sprite("nubes");
  const dinoFrames = [sprite("d1"), sprite("d2"), sprite("d3")];
  const treeImg = sprite("arbol");
  const texts = {
    es: { restart: "Pulsa ENTER o toca para reiniciar", best: "MEJOR" },
    en: { restart: "Press ENTER or tap to restart", best: "BEST" },
  };
  const t = document.documentElement.lang === "en" ? texts.en : texts.es;

  const floorX = canvas.width / 2 - 100;
  const floorY = canvas.height / 2 + 30;
  const skyHeight = canvas.height / 2 + 50;
  const speedStep = 300;
  let dino, cloudA, cloudB, trees, frame, frameTick, jumping, jumpSpeed, speed, nextTree, jumped, score, running, best = 0, timer;

  function reset() {
    dino = { x: floorX, y: floorY, width: 30, height: 38 };
    cloudA = { x: 0, y: 0, width: canvas.width, height: canvas.height / 2 - 50 };
    cloudB = { x: canvas.width, y: 0, width: canvas.width, height: canvas.height / 2 - 50 };
    trees = [];
    frame = 0;
    frameTick = 0;
    jumping = false;
    jumpSpeed = 0;
    speed = 6;
    nextTree = true;
    jumped = 0;
    score = 0;
    running = true;
  }

  function jump() {
    if (!running || jumping) return;
    jumpSpeed = -speed;
    jumping = true;
  }

  function drawBackground() {
    ctx.fillStyle = "#00FFFF";
    ctx.fillRect(0, 0, canvas.width, skyHeight);
    cloudA.x -= speed;
    cloudB.x -= speed;
    if (cloudA.x <= -canvas.width) cloudA.x = canvas.width;
    if (cloudB.x <= -canvas.width) cloudB.x = canvas.width;
    ctx.drawImage(clouds, cloudA.x, cloudA.y, cloudA.width, cloudA.height);
    ctx.drawImage(clouds, cloudB.x, cloudB.y, cloudB.width, cloudB.height);
    ctx.fillStyle = "#FF0000";
    ctx.font = "bold 22px sans-serif";
    ctx.textAlign = "right";
    ctx.fillText(`${t.best} ${best}   ${score}`, canvas.width - 24, 40);
    ctx.textAlign = "left";
    ctx.fillStyle = "#B45F04";
    ctx.fillRect(0, skyHeight, canvas.width, canvas.height - skyHeight);
    ctx.beginPath();
    ctx.moveTo(0, skyHeight);
    ctx.lineTo(canvas.width, skyHeight);
    ctx.strokeStyle = "black";
    ctx.stroke();
  }

  function updateJump() {
    if (!jumping) return;
    dino.y += jumpSpeed;
    if (dino.y <= floorY - 100) {
      dino.y = floorY - 100;
      jumpSpeed = speed + 1;
    }
    if (dino.y >= floorY) {
      dino.y = floorY;
      jumping = false;
    }
  }

  function drawDino() {
    frameTick++;
    if (frameTick === 6) {
      frame = (frame + 1) % 3;
      frameTick = 0;
    }
    ctx.drawImage(dinoFrames[frame], dino.x, dino.y, dino.width, dino.height);
  }

  function updateTrees() {
    if (nextTree) {
      trees.push({ x: canvas.width + Math.random() * 200, y: floorY - 35, width: 50, height: 70 });
      nextTree = false;
    }
    for (const tree of trees) {
      if (tree.x < -tree.width) continue;
      tree.x -= speed;
      ctx.drawImage(treeImg, tree.x, tree.y, tree.width, tree.height);
      if (tree.x <= dino.x && tree.x > dino.x - speed) jumped++;
    }
    trees = trees.filter((tree) => tree.x >= -tree.width);
    const last = trees[trees.length - 1];
    if (!last || last.x < canvas.width - 180) nextTree = true;
  }

  function checkCollisions() {
    const hit = trees.some(
      (tree) =>
        dino.x + dino.width >= tree.x + 20 &&
        dino.x <= tree.x + tree.width - 20 &&
        dino.y + dino.height >= tree.y + 20,
    );
    if (!hit) return;
    running = false;
    best = Math.max(best, score);
    ctx.save();
    ctx.fillStyle = "black";
    ctx.globalAlpha = 0.5;
    ctx.fillRect(0, 0, canvas.width, canvas.height);
    ctx.globalAlpha = 1;
    ctx.fillStyle = "white";
    ctx.font = "bold 30px sans-serif";
    ctx.textAlign = "center";
    ctx.fillText(t.restart, canvas.width / 2, canvas.height / 2);
    ctx.restore();
  }

  function loop() {
    if (!running) return;
    drawBackground();
    updateJump();
    drawDino();
    updateTrees();
    score = jumped * 20;
    speed = Math.min(16, 6 + Math.floor(score / speedStep));
    checkCollisions();
  }

  function restartOrJump() {
    if (running) jump();
    else reset();
  }

  window.addEventListener("keydown", (event) => {
    if (event.code === "Space" || event.code === "ArrowUp") {
      event.preventDefault();
      jump();
    } else if (event.code === "Enter" && !running) {
      reset();
    }
  });
  canvas.addEventListener("pointerdown", restartOrJump);

  reset();
  timer = window.setInterval(loop, 1000 / 50);
  window.addEventListener("pagehide", () => window.clearInterval(timer));
})();

