    trees = [];
    frame = 0;
    frameTick = 0;
    jumping = false;
    jumpSpeed = 0;
    speed = 6;
    nextTree = true;
    jumped = 0;
    score = 0;
    running = true;
  }

  function jump() {
    if (!running || jumping) return;
    jumpSpeed = -speed;
    jumping = true;
  }

  function drawBackground() {
    ctx.fillStyle = "#00FFFF";
