    ctx.beginPath();
    ctx.moveTo(0, skyHeight);
    ctx.lineTo(canvas.width, skyHeight);
    ctx.strokeStyle = "black";
    ctx.stroke();
  }

  function updateJump() {
    if (!jumping) return;
    dino.y += jumpSpeed;
    if (dino.y <= floorY - 100) {
      dino.y = floorY - 100;
      jumpSpeed = speed + 1;
    }
    if (dino.y >= floorY) {
      dino.y = floorY;
      jumping = false;
    }
  }

  function drawDino() {
    frameTick++;
    if (frameTick === 6) {
      frame = (frame + 1) % 3;
      frameTick = 0;
    }
    ctx.drawImage(dinoFrames[frame], dino.x, dino.y, dino.width, dino.height);
  }

  function updateTrees() {
    if (nextTree) {
      trees.push({ x: canvas.width + Math.random() * 200, y: floorY - 35, width: 50, height: 70 });
      nextTree = false;
    }
    for (const tree of trees) {
      if (tree.x < -tree.width) continue;
      tree.x -= speed;
      ctx.drawImage(treeImg, tree.x, tree.y, tree.width, tree.height);
      if (tree.x <= dino.x && tree.x > dino.x - speed) jumped++;
    }
    trees = trees.filter((tree) => tree.x >= -tree.width);
    const last = trees[trees.length - 1];
    if (!last || last.x < canvas.width - 180) nextTree = true;
  }

  function checkCollisions() {
    const hit = trees.some(
      (tree) =>
        dino.x + dino.width >= tree.x + 20 &&
        dino.x <= tree.x + tree.width - 20 &&
        dino.y + dino.height >= tree.y + 20,
    );
    if (!hit) return;
    running = false;
    best = Math.max(best, score);
    ctx.save();
    ctx.fillStyle = "black";
    ctx.globalAlpha = 0.5;
    ctx.fillRect(0, 0, canvas.width, canvas.height);
    ctx.globalAlpha = 1;
    ctx.fillStyle = "white";
    ctx.font = "bold 30px sans-serif";
    ctx.textAlign = "center";
    ctx.fillText(t.restart, canvas.width / 2, canvas.height / 2);
    ctx.restore();
  }

  function loop() {
    if (!running) return;
    drawBackground();
    updateJump();
    drawDino();
    updateTrees();
    score = jumped * 20;
    speed = Math.min(16, 6 + Math.floor(score / speedStep));
    checkCollisions();
  }

  function restartOrJump() {
    if (running) jump();
    else reset();
  }

  window.addEventListener("keydown", (event) => {
    if (event.code === "Space" || event.code === "ArrowUp") {
