// Offline-dino style runner for the 404 page. Colours follow the active portfolio theme.
(() => {
  const canvas = document.getElementById("dino-canvas");
  if (!canvas) return;
  const ctx = canvas.getContext("2d");
  const W = canvas.width;
  const H = canvas.height;
  const GROUND = H - 40;
  const PX = 3;
  const GRAVITY = 0.62;
  const JUMP = -11.5;
  const t = document.documentElement.lang === "en"
    ? { start: "PRESS SPACE OR TAP TO START", over: "GAME OVER - SPACE / ENTER / TAP", hi: "HI" }
    : { start: "PULSA ESPACIO O TOCA PARA EMPEZAR", over: "GAME OVER - ESPACIO / ENTER / TOCA", hi: "HI" };

  const body = [
    "......########..",
    "......##.#######",
    "......##########",
    "......##########",
    "......#####.....",
    "#....######.....",
    "#...#######.....",
    "##.#########.#..",
    "#############.#.",
    ".###########....",
    "..##########....",
    "...########.....",
    "....#######.....",
  ];
  const legs = [
    [".....###.###....", ".....##...#.....", ".....#....#.....", ".....##...##...."],
    [".....###.###....", ".....#...##.....", ".....#...#......", ".....##..##....."],
  ];
  const DINO_W = 16 * PX;
  const DINO_H = (body.length + 4) * PX;

  let colors, dino, cacti, ground, speed, score, running, started, legFrame, legTick, spawnIn, last;
  let best = 0;

  function readColors() {
    const s = getComputedStyle(document.body);
    colors = {
      ink: s.getPropertyValue("--ink").trim() || "#090b0a",
      paper: s.getPropertyValue("--paper").trim() || "#e9eee8",
      muted: s.getPropertyValue("--muted").trim() || "#858c85",
      accent: s.getPropertyValue("--green").trim() || "#20ef4f",
    };
  }

  function reset() {
    dino = { x: 60, y: GROUND - DINO_H, vy: 0, onGround: true };
    cacti = [];
    ground = [];
    for (let x = 0; x < W; x += 40) ground.push({ x, w: 6 + Math.random() * 18 });
    speed = 6;
    score = 0;
    running = true;
    legFrame = 0;
    legTick = 0;
    spawnIn = 60;
  }

  function jump() {
    if (!started) started = true;
    if (!running) return reset();
    if (dino.onGround) {
      dino.vy = JUMP;
      dino.onGround = false;
    }
  }

  function spawn() {
    const count = 1 + Math.floor(Math.random() * 3);
    const h = 34 + Math.floor(Math.random() * 26);
    cacti.push({ x: W + 10, w: 14 * count + 4 * (count - 1), h, count });
    spawnIn = 55 + Math.random() * 70 + speed * 4;
  }

  function drawSprite(rows, ox, oy) {
    rows.forEach((row, y) => {
      for (let x = 0; x < row.length; x++) {
        if (row[x] === "#") ctx.fillRect(ox + x * PX, oy + y * PX, PX, PX);
      }
    });
  }

  function drawCactus(c) {
    const y = GROUND - c.h;
    for (let i = 0; i < c.count; i++) {
      const x = c.x + i * 18;
      ctx.fillRect(x + 4, y, 6, c.h);
      ctx.fillRect(x, y + c.h * 0.35, 4, 4);
      ctx.fillRect(x, y + c.h * 0.2, 4, c.h * 0.2);
      ctx.fillRect(x + 10, y + c.h * 0.5, 4, 4);
      ctx.fillRect(x + 10, y + c.h * 0.3, 4, c.h * 0.25);
    }
  }

  function hit() {
    const d = { x: dino.x + 8, y: dino.y + 4, w: DINO_W - 16, h: DINO_H - 8 };
    return cacti.some((c) => d.x < c.x + c.w - 2 && d.x + d.w > c.x + 2 && d.y + d.h > GROUND - c.h + 2);
  }

  function update(k) {
    speed = Math.min(15, 6 + score / 400);
    score += speed * 0.1 * k;
    dino.vy += GRAVITY * k;
    dino.y += dino.vy * k;
    if (dino.y >= GROUND - DINO_H) {
      dino.y = GROUND - DINO_H;
      dino.vy = 0;
      dino.onGround = true;
    }
    legTick += k;
    if (legTick >= 6) {
      legTick = 0;
      legFrame = 1 - legFrame;
    }
    spawnIn -= k;
    if (spawnIn <= 0) spawn();
    cacti.forEach((c) => (c.x -= speed * k));
    cacti = cacti.filter((c) => c.x + c.w > -10);
    ground.forEach((g) => {
      g.x -= speed * k;
      if (g.x + g.w < 0) {
        g.x += W + 40;
        g.w = 6 + Math.random() * 18;
      }
    });
    if (hit()) {
      running = false;
      best = Math.max(best, Math.floor(score));
    }
  }

  function draw() {
    ctx.fillStyle = colors.ink;
    ctx.fillRect(0, 0, W, H);
    ctx.fillStyle = colors.muted;
    ctx.fillRect(0, GROUND, W, 1);
    ground.forEach((g) => ctx.fillRect(g.x, GROUND + 8 + (Math.floor(g.w) % 3) * 5, g.w, 2));
    ctx.fillStyle = colors.paper;
    cacti.forEach(drawCactus);
    ctx.fillStyle = colors.accent;
    drawSprite(body, dino.x, dino.y);
    drawSprite(dino.onGround && running ? legs[legFrame] : legs[0], dino.x, dino.y + body.length * PX);
    ctx.font = "bold 18px monospace";
    ctx.textAlign = "right";
    ctx.fillStyle = colors.muted;
    ctx.fillText(`${t.hi} ${String(best).padStart(5, "0")}`, W - 110, 30);
    ctx.fillStyle = colors.paper;
    ctx.fillText(String(Math.floor(score)).padStart(5, "0"), W - 20, 30);
    ctx.textAlign = "center";
    ctx.fillStyle = colors.accent;
    if (!started) ctx.fillText(t.start, W / 2, H / 2 - 20);
    else if (!running) ctx.fillText(t.over, W / 2, H / 2 - 20);
  }

  function frame(now) {
    const k = Math.min(3, (now - (last || now)) / 16.67);
    last = now;
    if (started && running) update(k);
    draw();
    requestAnimationFrame(frame);
  }

  window.addEventListener("keydown", (event) => {
    if (event.code === "Space" || event.code === "ArrowUp") {
      event.preventDefault();
      if (!event.repeat) jump();
    } else if (event.code === "Enter" && !running && !event.target.closest("a")) {
      jump();
    }
  });
  canvas.addEventListener("pointerdown", jump);
  document.addEventListener("visibilitychange", () => (last = 0));

  readColors();
  reset();
  requestAnimationFrame(frame);
})();

